CREATE TABLE sales_order(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,branch_id UUID NOT NULL,customer_id UUID,kind VARCHAR(10) NOT NULL CHECK(kind IN ('QUOTE','ORDER')),status VARCHAR(12) NOT NULL CHECK(status IN ('DRAFT','APPROVED','CONVERTED','CANCELLED')),version BIGINT NOT NULL DEFAULT 0,valid_until DATE NOT NULL,note VARCHAR(500) NOT NULL,items_json TEXT NOT NULL,cart_hash VARCHAR(64) NOT NULL,total NUMERIC(19,2) NOT NULL CHECK(total>0),sale_id UUID,created_by UUID NOT NULL,approved_by UUID,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,id),UNIQUE(tenant_id,sale_id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customer(tenant_id,id),FOREIGN KEY(tenant_id,sale_id) REFERENCES pos_sale(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES app_user(tenant_id,id),FOREIGN KEY(tenant_id,approved_by) REFERENCES app_user(tenant_id,id));
CREATE INDEX ix_sales_order_branch ON sales_order(tenant_id,branch_id,status,created_at);
